catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (newValue == '') {
        return;
    }

    var ga = new GlideAjax("x_hccc_hoc_ohs.HoCOHSMUtils");
    ga.addParam("sysparm_name", "getParentOHSMDetails");
    ga.addParam("sysparm_task_num", newValue);
    ga.getXMLAnswer(getParentDetails);


    function getParentDetails(response) {
        var result = JSON.parse(response); //transform the JSON string to an object

        g_form.setValue("location_s_of_the_occurrence_s", result.hv_location_occurence);
        g_form.setValue("witnesses_names_contact_information", result.hv_witnesses_name);
        g_form.setValue("date_s_of_the_occurrence_s", result.hv_date_of_occurence);
        g_form.setValue("individuals_involved_description", result.hv_indiv_inv_des);
        g_form.setValue("pre_meas", result.hv_pre_mea);

    }
}
